16	      setTags(await res.json());
17	    }
18	  }
19	
20	  async function loadCatalogue() {
21	    const res = await fetch('/api/tags');
22	    if (res.ok) {
23	      const list: Tag[] = await res.json();
24	      setCatalogue(list);
25	      setSelected((prev) => prev || (list[0] ? String(list[0].id) : ''));
26	    }
27	  }
28	
29	  useEffect(() => {
30	    void loadTags();
31	  }, [projectId]);
32	
